CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, name TEXT NOT NULL, line_user_id TEXT UNIQUE, timezone TEXT DEFAULT 'Asia/Bangkok', language TEXT DEFAULT 'th', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS cats (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, name TEXT NOT NULL, gender TEXT CHECK(gender IN ('M', 'F')), breed TEXT, date_of_birth DATE, weight_kg REAL, health_status TEXT DEFAULT 'normal' CHECK(health_status IN ('normal', 'treating', 'caution')), microchip_id TEXT, photo_url TEXT, chronic_diseases TEXT, drug_allergies TEXT, forbidden_foods TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS vaccinations (id TEXT PRIMARY KEY, cat_id TEXT NOT NULL, vaccine_name TEXT NOT NULL, vaccination_date DATE NOT NULL, expiration_date DATE, clinic_name TEXT, veterinarian_name TEXT, lot_number TEXT, notes TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (cat_id) REFERENCES cats(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS medications (id TEXT PRIMARY KEY, cat_id TEXT NOT NULL, medicine_name TEXT NOT NULL, dosage TEXT, frequency TEXT, route TEXT CHECK(route IN ('oral', 'liquid', 'topical', 'injection')), start_date DATE NOT NULL, end_date DATE, purpose TEXT, side_effects TEXT, is_active BOOLEAN DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (cat_id) REFERENCES cats(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS medical_history (id TEXT PRIMARY KEY, cat_id TEXT NOT NULL, record_date DATE NOT NULL, type TEXT NOT NULL CHECK(type IN ('illness', 'injury', 'checkup', 'surgery')), symptoms TEXT, diagnosis TEXT, clinic_name TEXT, veterinarian_name TEXT, treatment_date DATE, cost REAL, treatment_result TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (cat_id) REFERENCES cats(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS diet_info (id TEXT PRIMARY KEY, cat_id TEXT NOT NULL, food_name TEXT NOT NULL, food_type TEXT CHECK(food_type IN ('dry', 'wet', 'mixed')), portion_size REAL, unit TEXT CHECK(unit IN ('g', 'ml', 'cup')), frequency_per_day INTEGER, is_main_food BOOLEAN DEFAULT FALSE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (cat_id) REFERENCES cats(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS feeding_schedule (id TEXT PRIMARY KEY, cat_id TEXT NOT NULL, time_of_day TEXT NOT NULL, diet_id TEXT, is_enabled BOOLEAN DEFAULT TRUE, notification_enabled BOOLEAN DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (cat_id) REFERENCES cats(id) ON DELETE CASCADE, FOREIGN KEY (diet_id) REFERENCES diet_info(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS notifications (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, cat_id TEXT, type TEXT NOT NULL CHECK(type IN ('vaccine', 'medication', 'checkup', 'diet', 'reminder')), title TEXT NOT NULL, message TEXT NOT NULL, status TEXT DEFAULT 'pending' CHECK(status IN ('pending', 'sent', 'failed')), scheduled_date TIMESTAMP NOT NULL, sent_date TIMESTAMP, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY (cat_id) REFERENCES cats(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_cats_user_id ON cats(user_id);
CREATE INDEX IF NOT EXISTS idx_vaccinations_cat_id ON vaccinations(cat_id);
CREATE INDEX IF NOT EXISTS idx_vaccinations_expiration ON vaccinations(expiration_date);
CREATE INDEX IF NOT EXISTS idx_medications_cat_id ON medications(cat_id);
CREATE INDEX IF NOT EXISTS idx_medical_history_cat_id ON medical_history(cat_id);
CREATE INDEX IF NOT EXISTS idx_diet_info_cat_id ON diet_info(cat_id);
CREATE INDEX IF NOT EXISTS idx_feeding_schedule_cat_id ON feeding_schedule(cat_id);
CREATE INDEX IF NOT EXISTS idx_notifications_user_id ON notifications(user_id);
CREATE INDEX IF NOT EXISTS idx_notifications_status ON notifications(status);
CREATE INDEX IF NOT EXISTS idx_notifications_scheduled ON notifications(scheduled_date);
